def subtract(a, b):
    # Normalize intervals: remove empty intervals and sort
    def normalize(intervals):
        valid = [interval for interval in intervals if interval[0] < interval[1]]
        if not valid:
            return []
        valid.sort()
        return valid

    a_normalized = normalize(a)
    b_normalized = normalize(b)

    if not a_normalized:
        return []

    if not b_normalized:
        return a_normalized

    # Merge overlapping/touching intervals in b to create a coverage map
    def merge_intervals(intervals):
        if not intervals:
            return []
        merged = [intervals[0]]
        for current in intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                # Overlapping or touching, merge
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                merged.append(current)
        return merged

    b_merged = merge_intervals(b_normalized)

    # For each interval in a, subtract all intervals in b_merged
    result = []

    for [a_start, a_end] in a_normalized:
